INSERT INTO `ad_zones` VALUES (1,'header_leaderboard','Header Leaderboard','Header Leaderboard placement.',728,90,'top',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(2,'header_mobile','Header Mobile Banner','Header Mobile Banner placement.',320,50,'top',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(3,'post_inline','In-Article Banner','In-Article Banner placement.',728,90,'inline',1,2,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(4,'post_inline_2','In-Article #2','In-Article #2 placement.',300,600,'inline',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(5,'sidebar_box','Sidebar Medium Rect','Sidebar Medium Rect placement.',300,250,'sidebar',1,3,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(6,'sidebar_skyscraper','Sidebar Skyscraper','Sidebar Skyscraper placement.',160,600,'sidebar',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(7,'footer_banner','Footer Banner','Footer Banner placement.',970,250,'footer',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12'),(8,'popup_interstitial','Interstitial Popup','Interstitial Popup placement.',600,400,'popup',1,1,'2026-10-03 01:59:12','2026-10-03 01:59:12');
