INSERT INTO `page_translations` VALUES (1,1,1,'About Blogger4U','about','<h2>About Blogger4U</h2>\n<p>Blogger4U is a modern, AI-assisted news and magazine CMS built on Laravel 13 and Livewire 4. We help editorial teams ship faster — from brainstorming a headline to publishing the article — with the help of OpenAI and Gemini integrations baked into every step of the workflow.</p>\n<p>This demo content is fully editable. Sign in as <code>admin@blogger4u.test</code> (password: <code>password</code>) to explore the admin.</p>','About Blogger4U — Blogger4U','About Blogger4U\nBlogger4U is a modern, AI-assisted news and magazine CMS built on Laravel 13 and Livewire 4. We help editorial teams ship faster — from bra...',NULL,1,'2026-10-03 01:59:09','2026-10-03 01:59:09'),(2,2,1,'Contact Us','contact','<h2>Get in touch</h2>\n<p>Editorial: <a href=\"mailto:editor@blogger4u.test\">editor@blogger4u.test</a></p>\n<p>Advertising: <a href=\"mailto:ads@blogger4u.test\">ads@blogger4u.test</a></p>','Contact Us — Blogger4U','Get in touch\nEditorial: editor@blogger4u.test\nAdvertising: ads@blogger4u.test',NULL,1,'2026-10-03 01:59:09','2026-10-03 01:59:09'),(3,3,1,'Privacy Policy','privacy','<h2>Privacy Policy</h2>\n<p>This is a placeholder Privacy Policy shipped with the Blogger4U demo. Replace it with the wording your lawyers approve before going live.</p>','Privacy Policy — Blogger4U','Privacy Policy\nThis is a placeholder Privacy Policy shipped with the Blogger4U demo. Replace it with the wording your lawyers approve before going live.',NULL,1,'2026-10-03 01:59:09','2026-10-03 01:59:09'),(4,4,1,'Terms of Service','terms','<h2>Terms of Service</h2>\n<p>This is a placeholder Terms of Service shipped with the Blogger4U demo.</p>','Terms of Service — Blogger4U','Terms of Service\nThis is a placeholder Terms of Service shipped with the Blogger4U demo.',NULL,1,'2026-10-03 01:59:09','2026-10-03 01:59:09');
