--
-- Table structure for table `post_translations`
--

DROP TABLE IF EXISTS `post_translations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `post_translations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_id` bigint unsigned NOT NULL,
  `language_id` bigint unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `excerpt` text COLLATE utf8mb4_unicode_ci,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `reading_time` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb4_unicode_ci,
  `focus_keyword` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `canonical_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `og_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_score` tinyint unsigned DEFAULT NULL,
  `translation_status` enum('manual','ai_generated','ai_reviewed','human_reviewed','published') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `translated_at` timestamp NULL DEFAULT NULL,
  `translated_by` bigint unsigned DEFAULT NULL,
  `ai_translation_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `post_trans_unique` (`post_id`,`language_id`),
  UNIQUE KEY `post_trans_slug_per_lang` (`language_id`,`slug`),
  KEY `post_translations_translated_by_foreign` (`translated_by`),
  KEY `post_translations_language_id_is_published_index` (`language_id`,`is_published`),
  KEY `post_translations_focus_keyword_index` (`focus_keyword`),
  FULLTEXT KEY `post_translations_title_content_fulltext` (`title`,`content`),
  CONSTRAINT `post_translations_language_id_foreign` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_translations_post_id_foreign` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_translations_translated_by_foreign` FOREIGN KEY (`translated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

